#include <Arduino_GFX_Library.h>

#define GFX_BL 1

Arduino_DataBus *bus = new Arduino_ESP32QSPI(
  45, 47, 21, 48, 40, 39
  );

  Arduino_GFX *panel = new Arduino_AXS15231B(
    bus,
      GFX_NOT_DEFINED,
        0,
          false,
            320,
              480,
                0, 0, 0, 0,
                  axs15231b_320480_type1_init_operations,
                    sizeof(axs15231b_320480_type1_init_operations)
                    );

                    Arduino_Canvas *gfx = new Arduino_Canvas(
                      320, 480, panel, 0, 0, 0
                      );

                      void setup() {
                        pinMode(GFX_BL, OUTPUT);
                          digitalWrite(GFX_BL, HIGH);

                            gfx->begin();
                              delay(500);
                              }

                              void loop() {
                                gfx->fillScreen(0xF800); // Красный
                                  gfx->flush();
                                    delay(1000);

                                      gfx->fillScreen(0x07E0); // Зеленый
                                        gfx->flush();
                                          delay(1000);

                                            gfx->fillScreen(0x001F); // Синий
                                              gfx->flush();
                                                delay(1000);

                                                  gfx->fillScreen(0xFFFF); // Белый
                                                    gfx->flush();
                                                      delay(1000);

                                                        gfx->fillScreen(0x0000); // Черный
                                                          gfx->flush();
                                                            delay(1000);
                                                            }
